<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import request from '@/utils/request'
const form=reactive({enabled:false,host:'',port:465,security:'SSL',username:'',password:'',from:'',recipients:''})
const hasPassword=ref(false),loading=ref(false),saving=ref(false),testing=ref(false)
async function load(){loading.value=true;try{const data=(await request({url:'/monitor/mail/config',method:'get'})).data||{};Object.assign(form,{...data,password:''});hasPassword.value=!!data.hasPassword}finally{loading.value=false}}
async function save(){if(!form.host.trim()||!form.username.trim()||!form.from.trim()||!form.recipients.trim())return ElMessage.warning('请填写服务器、账号、发件人和收件人');saving.value=true;try{await request({url:'/monitor/mail/config',method:'put',data:{...form}});ElMessage.success('配置已保存');await load()}finally{saving.value=false}}
async function test(){testing.value=true;try{await request({url:'/monitor/mail/test',method:'post'});ElMessage.success('测试邮件已发送，请查看收件箱')}finally{testing.value=false}}
onMounted(load)
</script>
<template><main class="page" v-loading="loading"><header><span>通知管理</span><h1>邮箱通知</h1><p>设备报修及维修完成后，向指定邮箱发送通知。</p></header><section><div class="heading"><div><h2>邮箱配置</h2><p>填写邮箱服务商提供的 SMTP 信息。</p></div><el-switch v-model="form.enabled" active-text="启用通知"/></div><el-form label-position="top" @submit.prevent><el-form-item label="SMTP 服务器" required><el-input v-model="form.host" placeholder="例如 smtp.example.com"/></el-form-item><div class="row"><el-form-item label="端口" required><el-input-number v-model="form.port" :min="1" :max="65535"/></el-form-item><el-form-item label="连接安全"><el-select v-model="form.security"><el-option label="SSL/TLS" value="SSL"/><el-option label="STARTTLS" value="STARTTLS"/><el-option label="不加密" value="NONE"/></el-select></el-form-item></div><el-form-item label="邮箱账号" required><el-input v-model="form.username" autocomplete="off"/></el-form-item><el-form-item label="授权码或密码"><el-input v-model="form.password" type="password" show-password autocomplete="new-password" :placeholder="hasPassword ? '已配置，留空保持不变' : '填写邮箱服务商提供的授权码'"/></el-form-item><el-form-item label="发件人邮箱" required><el-input v-model="form.from" placeholder="例如 sender@example.com"/></el-form-item><el-form-item label="收件人邮箱" required><el-input v-model="form.recipients" type="textarea" :rows="3" placeholder="多个邮箱用英文逗号分隔"/></el-form-item></el-form><div class="actions"><el-button type="primary" :loading="saving" @click="save">保存配置</el-button><el-button :loading="testing" @click="test">发送测试邮件</el-button></div><p class="hint">测试使用已保存的配置，修改后请先保存。</p></section></main></template>
<style scoped>.page{max-width:920px;margin:auto;padding:28px;color:#1d3449}header{margin-bottom:24px}header span,p{color:#6e8193}h1{font-size:26px;margin:8px 0}p{line-height:1.6;margin:0}section{padding:26px;background:#fff;border:1px solid #e6edf3;border-radius:14px}.heading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:24px}.heading h2{font-size:18px;margin:0 0 8px}.row{display:grid;grid-template-columns:1fr 1fr;gap:16px}.row :deep(.el-input-number),.row :deep(.el-select){width:100%}.actions{display:flex;gap:8px}.actions :deep(.el-button){margin:0}.hint{font-size:13px;margin-top:12px}@media(max-width:600px){.page{padding:16px}section{padding:18px}.heading{display:block}.heading :deep(.el-switch){margin-top:16px}.row{grid-template-columns:1fr}.actions{flex-wrap:wrap}}</style>
